fn reverse(a: Vec<char>) -> Vec<char> {
    // We consume the input Vec<char> via `into_iter()`, which yields
    // its elements by value. Because Vec<T>::IntoIter implements
    // DoubleEndedIterator, we can call `.rev()` on it to iterate in reverse.
    // Finally, we collect the reversed iterator into a new Vec<char>.
    a.into_iter().rev().collect()
}

